git_commands:
Set-Location 'trials/opus5-A2\repo'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
"== reflog files:"
Get-ChildItem -Force -Recurse .git\logs -File | ForEach-Object { $_.FullName.Substring((Resolve-Path .git).Path.Length + 1) }
foreach ($r in 'refs/heads/fix/typo','refs/heads/wip/new-feature','refs/heads/main','HEAD') {
  "== reflog $r :"; git reflog show --format='%h %gd | %gs' $r
}
"== ORIG_HEAD: " + (git rev-parse ORIG_HEAD) + " ; branches containing it:"; git branch -a --contains ORIG_HEAD
"== commits in any reflog not reachable from any branch/remote ref:"
$reach = git rev-list --branches --remotes
$all = git rev-list --reflog --all 2>$null
$orphans = $all | Where-Object { $_ -notin $reach }
if ($orphans) { $orphans | ForEach-Object { git log -1 --format='%h %ad %s' --date=short $_ } } else { '(none)' }
"== fsck dangling/unreachable commits:"
git fsck --no-reflogs --unreachable --no-progress 2>&1 | Select-String 'commit'
